import java.io.*;
import java.util.*;

public class Solution {
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
            st = null;
        }

        String getNext() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    System.out.println(e);
                }
            }
            return st.nextToken();
        }

        int getInt() {
            return Integer.parseInt(getNext());
        }

        long getLong() {
            return Long.parseLong(getNext());
        }

        double getDouble() {
            return Double.parseDouble(getNext());
        }

        String getLine() {
            try {
                if (st == null || !st.hasMoreTokens()) {
                    st = new StringTokenizer(br.readLine());
                }
            } catch (IOException e) {
                System.out.println(e);
            }
            return st.nextToken("\n");
        }
    }

    static final long MOD = 998244353L;
    static final int MAX = 200005;
    static long[] fact = new long[MAX];

    static long fastExp(long base, long exp, long mod) {
        long res = 1L;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }

    static long combination(int n, int r) {
        if (r > n) return 0L;
        return fact[n] * fastExp(fact[r], MOD - 2, MOD) % MOD * fastExp(fact[n - r], MOD - 2, MOD) % MOD;
    }

    static long calc(int n, int k) {
        long sum = 0;
        for (int i = 0; i <= n - k; i++) {
            long val = combination(n - k, i) * fastExp(n - k - i, n, MOD) % MOD;
            if (i % 2 == 0) sum = (sum + val) % MOD;
            else sum = (sum - val + MOD) % MOD;
        }
        return sum;
    }

    public static void main(String[] args) {
        FastReader fr = new FastReader();
        int t = 1;
        // t = fr.getInt();
        for (int i = 0; i < t; i++) {
            long n = fr.getLong();
            long k = fr.getLong();
            fact[0] = 1;
            for (long j = 1; j <= n; j++) {
                fact[(int) j] = fact[(int) (j - 1)] * j % MOD;
            }
            if (k >= n) {
                System.out.println(0);
            } else if (k == 0) {
                System.out.println(fact[(int) n]);
            } else {
                long res = 2 * combination((int) n, (int) (n - k)) * calc((int) n, (int) k) % MOD;
                System.out.println(res);
            }
        }
    }
}
