#include <bits/stdc++.h>
using namespace std;

struct FastReader {
    std::istream& in;
    std::string token;
    std::queue<std::string> tokens;

    FastReader(std::istream& input_stream) : in(input_stream) {}

    std::string getNext() {
        while (tokens.empty()) {
            std::string line;
            if (!std::getline(in, line)) {
                return "";
            }
            std::istringstream iss(line);
            std::string temp;
            while (iss >> temp) {
                tokens.push(temp);
            }
        }
        std::string res = tokens.front();
        tokens.pop();
        return res;
    }

    int getInt() {
        return std::stoi(getNext());
    }

    long long getLong() {
        return std::stoll(getNext());
    }

    double getDouble() {
        return std::stod(getNext());
    }

    std::string getLine() {
        if (!tokens.empty()) {
            std::string remaining;
            std::getline(in, remaining);
            return remaining;
        } else {
            std::string line;
            std::getline(in, line);
            return line;
        }
